public class StatusBoard {
    private final Object lock = new Object();
    private final List<Consumer<String>> listeners = new ArrayList<>();
    private String status;

    public void subscribe(Consumer<String> l) {
        synchronized (lock) { listeners.add(l); }
    }

    public void update(String newStatus) {
        List<Consumer<String>> toNotify;
        synchronized (lock) {
            status = newStatus;
            toNotify = List.copyOf(listeners);
        }
        for (Consumer<String> l : toNotify) l.accept(newStatus);
    }
}

